begin;
-- Isolated, synthetic local records. No hosted business transactions.
create extension if not exists pgtap with schema extensions;select extensions.no_plan();
alter table auth.users disable trigger on_auth_user_created;
insert into auth.users(id,email) values('b6100000-0000-4000-8000-000000000001','receipt-owner@local.invalid'),('b6100000-0000-4000-8000-000000000002','receipt-worker@local.invalid'),('b6100000-0000-4000-8000-000000000003','receipt-foreign@local.invalid');
alter table auth.users enable trigger on_auth_user_created;
insert into public.companies(id,name,operating_timezone) values('b6200000-0000-4000-8000-000000000001','Synthetic receipt contractor','UTC'),('b6200000-0000-4000-8000-000000000002','Other receipt contractor','UTC');
insert into public.profiles(id,company_id,role) values('b6100000-0000-4000-8000-000000000001','b6200000-0000-4000-8000-000000000001','owner'),('b6100000-0000-4000-8000-000000000002','b6200000-0000-4000-8000-000000000001','employee'),('b6100000-0000-4000-8000-000000000003','b6200000-0000-4000-8000-000000000002','owner');
insert into public.projects(id,company_id,job_number,name,status) values('b6300000-0000-4000-8000-000000000001','b6200000-0000-4000-8000-000000000001','SYN-RECEIPT','Synthetic receipt job','active');
insert into public.invoices(id,company_id,project_id,invoice_number,invoice_type,status,issue_date,from_name,sales_tax_rate_percent,retainage_percent,created_by) values('b6400000-0000-4000-8000-000000000001','b6200000-0000-4000-8000-000000000001','b6300000-0000-4000-8000-000000000001','INV-SYN-RECEIPT','progress','sent','2026-10-16','Synthetic sender',10,10,'b6100000-0000-4000-8000-000000000001');
insert into public.invoice_lines(company_id,invoice_id,description,quantity,unit,unit_price,line_amount,taxable) values('b6200000-0000-4000-8000-000000000001','b6400000-0000-4000-8000-000000000001','Synthetic placed work',1,'LS',100,100,true);
create function pg_temp.receive(n integer,p jsonb) returns jsonb language sql as $$select public.carez_record_invoice_payment_v2(('b6500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'b6400000-0000-4000-8000-000000000001',p)$$;
create temp table receipt_input as select '{"amount":40,"processing_fee":2,"received_date":"2026-10-16","payment_method":"check","reference_number":"SYN-RECEIPT"}'::jsonb payload;grant select on receipt_input to authenticated;
select set_config('request.jwt.claim.sub','b6100000-0000-4000-8000-000000000001',true);set local role authenticated;
select extensions.is((select invoice_total from public.invoice_financial_summary where invoice_id='b6400000-0000-4000-8000-000000000001'),100::numeric,'existing invoice tax and retainage formula remains unchanged');
select extensions.lives_ok($$select pg_temp.receive(1,(select payload from receipt_input))$$,'payment and allocation commit through one command');
select extensions.lives_ok($$select pg_temp.receive(1,(select payload from receipt_input))$$,'same request replay returns confirmed receipt');
select extensions.is((select count(*)::integer from public.customer_payments),1,'retry creates one payment');
select extensions.is((select count(*)::integer from public.payment_allocations),1,'retry creates one allocation');
select extensions.is((select status from public.customer_payments),'posted','new receipt has explicit posted state');
select extensions.is((select balance_due from public.invoice_financial_summary where invoice_id='b6400000-0000-4000-8000-000000000001'),60::numeric,'recorded allocation changes authoritative balance once');
select extensions.is((select amount from public.customer_payments),40::numeric,'processing fee is separate from payment principal');
select extensions.throws_like($$select pg_temp.receive(1,(select payload||'{"amount":41}' from receipt_input))$$,'%reused with different values%','changed uncertain retry is rejected');
select extensions.throws_like($$select pg_temp.receive(2,(select payload||'{"amount":61}' from receipt_input))$$,'%greater than the current invoice balance%','overpayment uses the locked current balance');
select extensions.throws_like($$select pg_temp.receive(2,(select payload||'{"amount":"NaN"}' from receipt_input))$$,'%finite nonnegative%','nonfinite amount cannot post');
select extensions.throws_like($$select pg_temp.receive(2,(select payload||'{"amount":0}' from receipt_input))$$,'%finite nonnegative%','zero receipt cannot post');
select extensions.throws_like($$select pg_temp.receive(2,(select payload||'{"processing_fee":41}' from receipt_input))$$,'%fee cannot exceed%','fee cannot exceed principal');
select extensions.throws_like($$select pg_temp.receive(2,(select payload||'{"received_date":null}' from receipt_input))$$,'%Recorded date is required%','unknown arrival date does not become today');
select extensions.throws_like($$delete from public.payment_allocations$$,'%permission denied%','raw allocation deletion cannot erase customer balance');
select extensions.throws_like($$update public.customer_payments set status='void'$$,'%permission denied%','raw payment update cannot bypass the governed boundary');
reset role;
create function pg_temp.fail_receipt_allocation() returns trigger language plpgsql as $$begin raise exception 'Synthetic allocation failure';end$$;
create trigger synthetic_receipt_failure before insert on public.payment_allocations for each row execute function pg_temp.fail_receipt_allocation();
set local role authenticated;
select extensions.throws_like($$select pg_temp.receive(2,(select payload||'{"amount":13}' from receipt_input))$$,'%Synthetic allocation failure%','allocation failure is surfaced');
select extensions.is((select count(*)::integer from public.customer_payments),1,'allocation failure rolls back its payment');
select extensions.is((select count(*)::integer from public.financial_command_requests where command='record_invoice_payment'),1,'allocation failure rolls back its request');
reset role;drop trigger synthetic_receipt_failure on public.payment_allocations;
set local role authenticated;
select extensions.lives_ok($$select pg_temp.receive(2,(select payload||'{"amount":13,"processing_fee":0}' from receipt_input))$$,'failed submission can recover after the cause clears');
select extensions.is((select balance_due from public.invoice_financial_summary where invoice_id='b6400000-0000-4000-8000-000000000001'),47::numeric,'reopen shows the confirmed recovered receipt');
select set_config('request.jwt.claim.sub','b6100000-0000-4000-8000-000000000002',true);
select extensions.throws_like($$select pg_temp.receive(3,(select payload from receipt_input))$$,'%Owner or office authority required%','employee cannot record customer cash');
select set_config('request.jwt.claim.sub','b6100000-0000-4000-8000-000000000003',true);
select extensions.throws_like($$select pg_temp.receive(3,(select payload from receipt_input))$$,'%sent invoices%','other tenant cannot use this invoice');
reset role;set local role anon;
select extensions.throws_like($$select pg_temp.receive(3,'{}')$$,'%permission denied%','anonymous cannot record customer cash');
reset role;select * from extensions.finish();rollback;
